-- Part 4 of 4. Run the parts in order.
-- =====================================================================
-- Akeso reference data seed
-- 30 diseases, 74 symptoms, 49 medicines,
-- 97 drug-drug interaction pairs, 12 multi-drug rules.
--
-- Researched from StatPearls (NCBI Bookshelf), WHO, CDC, DOH Philippines,
-- PSMID/PCP, GINA, GOLD, ADA, AHA/ESC, NICE and FDA labels on DailyMed.
-- Every clinical reference URL was opened and checked when this file was
-- made. Textbook ("mother book") references carry no URL on purpose.
--
-- Educational reference content for a student platform, not a substitute
-- for current product labeling or clinical judgment.
--
-- Safe to run more than once: rows with these ids are updated, and their
-- child rows (lists, links, references) are replaced.
-- Requires database/migrations/001_medication_safety_reference.sql.
-- =====================================================================


BEGIN;

-- ============================================= DRUG INTERACTION CHECKER
-- Drug x patient condition


-- Drug x drug (stored once per pair, lower id first)


-- Multi-drug rules (members match drug_class keywords)

CREATE TEMP TABLE _seed_interaction_rules ON COMMIT DROP AS SELECT id, name, severity, description, clinical_significance, recommendation, required_condition_id, source_attribution, is_published FROM public.interaction_rules WITH NO DATA;
UPDATE public.interaction_rules AS x SET name = t.name, severity = t.severity, description = t.description, clinical_significance = t.clinical_significance, recommendation = t.recommendation, required_condition_id = t.required_condition_id, source_attribution = t.source_attribution, is_published = t.is_published, updated_at = now()
  FROM _seed_interaction_rules AS t WHERE x.id = t.id;
  SELECT id, name, severity, description, clinical_significance, recommendation, required_condition_id, source_attribution, is_published FROM _seed_interaction_rules AS t
  WHERE NOT EXISTS (SELECT 1 FROM public.interaction_rules AS x WHERE x.id = t.id);



-- Tell every installed app to re-download the reference data.
UPDATE public.content_version SET version = version + 1, updated_at = now() WHERE id = 1;

COMMIT;
