INSERT INTO public.medicine_condition_safety (medicine_id, condition_id, safety, summary, guidance, source_attribution) VALUES
    ('med_paracetamol', 'hypertension', 'safe', 'Generally preferred analgesic over NSAIDs in hypertension; no effect on RAAS or sodium retention at usual doses.', 'One trial in hypertensive patients found regular high-dose use raised daytime systolic BP by about 5 mmHg; use lowest effective dose.', 'StatPearls: Acetaminophen'),
    ('med_paracetamol', 'diabetes', 'safe', 'No condition-specific precaution in labeling.', 'Standard dosing.', 'FDA OTC Drug Facts label'),
    ('med_paracetamol', 'pregnant', 'safe', 'ACOG considers acetaminophen an appropriate analgesic/antipyretic in pregnancy.', 'Use lowest effective dose for shortest duration; observational studies have reported associations with reproductive/neurobehavioral outcomes.', 'StatPearls: Acetaminophen (Pregnancy considerations)'),
    ('med_paracetamol', 'asthma', 'safe', 'Commonly used as the antipyretic/analgesic alternative to aspirin and NSAIDs in asthma.', 'No asthma-specific precaution in the OTC label.', 'FDA OTC Drug Facts label; Goodman & Gilman''s 14th ed.'),
    ('med_paracetamol', 'peptic_ulcer', 'safe', 'Weak peripheral COX inhibition; not associated with the GI ulceration/bleeding seen with NSAIDs.', 'Preferred over NSAIDs/aspirin for analgesia when GI bleeding risk is a concern.', 'StatPearls: Acetaminophen; Goodman & Gilman''s 14th ed.'),
    ('med_paracetamol', 'renal_impairment', 'caution', 'Metabolites accumulate in severe renal impairment.', 'Extend dosing interval and reduce daily dose when CrCl <= 30 mL/min.', 'StatPearls: Acetaminophen (Renal impairment)'),
    ('med_paracetamol', 'liver_disease', 'caution', 'Hepatotoxic in overdose; contraindicated in severe hepatic impairment or severe active liver disease.', 'Reduce dose in mild impairment; OTC label advises asking a doctor before use with liver disease.', 'StatPearls: Acetaminophen; FDA OTC Drug Facts label'),
    ('med_paracetamol', 'autoimmune', 'safe', 'No condition-specific precaution in labeling; no immunosuppressive effect.', 'Standard dosing.', 'FDA OTC Drug Facts label'),
    ('med_ibuprofen', 'hypertension', 'caution', 'NSAIDs can cause new-onset or worsening hypertension and blunt the effect of ACE inhibitors, ARBs, beta-blockers and diuretics.', 'Monitor blood pressure during initiation and throughout therapy per label.', 'FDA label, Warnings and Precautions (Hypertension); StatPearls: Ibuprofen'),
    ('med_ibuprofen', 'pregnant', 'avoid', 'Fetal renal dysfunction/oligohydramnios from about 20 weeks and premature ductus arteriosus closure from about 30 weeks.', 'Avoid at >= 30 weeks; limit to lowest dose/shortest duration between 20 and 30 weeks, with ultrasound monitoring if > 48 hours.', 'FDA label, Warnings (Fetal toxicity); StatPearls: Ibuprofen'),
    ('med_ibuprofen', 'asthma', 'caution', 'Contraindicated in aspirin-sensitive asthma because of severe, potentially fatal bronchospasm.', 'Use with caution in pre-existing asthma; avoid in aspirin-exacerbated respiratory disease.', 'FDA label, Contraindications and Warnings (Exacerbation of asthma related to aspirin sensitivity)'),
    ('med_ibuprofen', 'peptic_ulcer', 'avoid', 'Boxed warning for GI bleeding, ulceration and perforation; prior ulcer disease or GI bleeding greatly increases risk.', 'Avoid in active ulcer/GI bleeding; if unavoidable in those with prior ulcer, use lowest dose/shortest duration with gastroprotection per clinician.', 'FDA label, Boxed Warning (GI risk); StatPearls: NSAIDs'),
    ('med_ibuprofen', 'renal_impairment', 'caution', 'Prostaglandin inhibition can reduce renal blood flow and precipitate acute kidney injury.', 'Not recommended in advanced renal disease per label; StatPearls advises avoiding if GFR < 30 mL/min and avoiding prolonged use if GFR < 60 mL/min.', 'FDA label, Warnings (Renal toxicity); StatPearls: Ibuprofen'),
    ('med_ibuprofen', 'liver_disease', 'caution', 'Elevations of liver enzymes and rare severe hepatic reactions reported.', 'Monitor liver function; discontinue if hepatic dysfunction develops.', 'FDA label, Warnings (Hepatotoxicity); StatPearls: Ibuprofen'),
    ('med_ibuprofen', 'autoimmune', 'caution', 'Aseptic meningitis with ibuprofen is more likely in patients with SLE and related connective tissue diseases.', 'Evaluate promptly for meningitis if fever, stiff neck or altered consciousness develop in patients with SLE.', 'FDA label, Precautions (Aseptic meningitis)'),
    ('med_mefenamic_acid', 'hypertension', 'caution', 'NSAIDs can raise blood pressure and reduce the effect of antihypertensives.', 'Monitor blood pressure during therapy per label.', 'FDA label, Warnings (Hypertension); StatPearls: NSAIDs'),
    ('med_mefenamic_acid', 'pregnant', 'avoid', 'NSAID fetal toxicity: oligohydramnios/fetal renal dysfunction from about 20 weeks, premature ductus closure from about 30 weeks.', 'Avoid at >= 30 weeks; limit use between 20 and 30 weeks.', 'FDA label, Warnings (Fetal toxicity)'),
    ('med_mefenamic_acid', 'asthma', 'caution', 'Contraindicated in patients with asthma/urticaria after aspirin or NSAIDs; may exacerbate aspirin-sensitive asthma.', 'Avoid in aspirin-exacerbated respiratory disease; use with caution in other asthma.', 'FDA label, Contraindications and Warnings'),
    ('med_mefenamic_acid', 'peptic_ulcer', 'avoid', 'Boxed warning for GI bleeding, ulceration and perforation; risk higher with prior ulcer disease.', 'Avoid in active peptic ulcer or GI bleeding.', 'FDA label, Boxed Warning; StatPearls: NSAIDs'),
    ('med_mefenamic_acid', 'renal_impairment', 'caution', 'NSAID-induced reduction of renal perfusion may cause renal decompensation.', 'Avoid in advanced renal disease per label.', 'FDA label, Warnings (Renal toxicity)'),
    ('med_mefenamic_acid', 'liver_disease', 'caution', 'Liver enzyme elevations reported; NSAIDs are generally avoided in hepatic dysfunction.', 'Monitor liver function; discontinue if hepatic dysfunction develops.', 'FDA label, Warnings (Hepatotoxicity); StatPearls: NSAIDs'),
    ('med_aspirin', 'hypertension', 'caution', 'OTC label advises asking a doctor before use with high blood pressure.', 'Use for vascular prevention is a clinician decision; ensure blood pressure is controlled.', 'FDA OTC Drug Facts label (Ask a doctor before use)'),
    ('med_aspirin', 'pregnant', 'caution', 'Low-dose aspirin is used to reduce preeclampsia risk in high-risk pregnancy; otherwise avoided late in pregnancy.', 'Low dose started between 12 and 28 weeks when indicated; label warns against use in the last 3 months unless directed by a doctor.', 'StatPearls: Aspirin; FDA OTC Drug Facts label (Pregnancy warning)'),
    ('med_aspirin', 'asthma', 'caution', 'Can trigger severe bronchospasm in aspirin-exacerbated respiratory disease.', 'Contraindicated in AERD; label advises asking a doctor before use with asthma.', 'StatPearls: Aspirin; FDA OTC Drug Facts label'),
    ('med_aspirin', 'peptic_ulcer', 'avoid', 'Irreversible COX-1 inhibition impairs gastric mucosal protection and platelet function, increasing ulcer bleeding.', 'Avoid with active ulcer or bleeding; risk also raised by prior ulcer, age >= 60, anticoagulants, steroids and alcohol.', 'FDA OTC Drug Facts label (Stomach bleeding warning); StatPearls: Aspirin'),
    ('med_aspirin', 'renal_impairment', 'caution', 'Increased bleeding risk and risk of renal deterioration.', 'Avoid in severe renal impairment (CrCl < 10 mL/min).', 'StatPearls: Aspirin (Renal impairment)'),
    ('med_aspirin', 'liver_disease', 'caution', 'Hepatic dysfunction increases bleeding risk.', 'Use cautiously; generally contraindicated in severe hepatic insufficiency; label advises asking a doctor with liver cirrhosis.', 'StatPearls: Aspirin; FDA OTC Drug Facts label'),
    ('med_clopidogrel', 'pregnant', 'caution', 'Limited human data; no evidence of increased malformation risk in reported pregnancies.', 'Use only if clearly needed; consider bleeding risk around labor and neuraxial anesthesia.', 'FDA label, Use in Specific Populations; StatPearls: Clopidogrel'),
    ('med_clopidogrel', 'peptic_ulcer', 'avoid', 'Contraindicated with active pathological bleeding such as bleeding peptic ulcer.', 'Avoid with active ulcer bleeding; history of ulcer increases GI bleeding risk.', 'FDA label, Contraindications'),
    ('med_clopidogrel', 'renal_impairment', 'caution', 'Limited experience in severe renal impairment; CKD is associated with reduced response and higher bleeding risk.', 'No specific dose adjustment; monitor for bleeding.', 'FDA label, Use in Specific Populations; StatPearls: Clopidogrel'),
    ('med_clopidogrel', 'liver_disease', 'safe', 'No dosage adjustment required in hepatic impairment per label.', 'Monitor for bleeding in patients with liver-related coagulopathy.', 'FDA label, Use in Specific Populations; StatPearls: Clopidogrel'),
    ('med_warfarin', 'hypertension', 'caution', 'Contraindicated in malignant hypertension; uncontrolled hypertension increases intracranial bleeding risk.', 'Avoid in malignant hypertension; control blood pressure during anticoagulation.', 'FDA label, Contraindications; StatPearls: Warfarin'),
    ('med_warfarin', 'pregnant', 'avoid', 'Crosses the placenta; causes embryopathy, fetal bleeding and pregnancy loss.', 'Contraindicated in pregnancy except in women with mechanical heart valves at high thromboembolic risk.', 'FDA label, Contraindications and Use in Specific Populations'),
    ('med_warfarin', 'peptic_ulcer', 'avoid', 'Contraindicated with active GI bleeding or ulceration.', 'Avoid with active ulcer bleeding; history of GI bleeding raises bleeding risk.', 'FDA label, Contraindications; StatPearls: Warfarin'),
    ('med_warfarin', 'renal_impairment', 'caution', 'No dose adjustment, but bleeding risk is higher and warfarin-related AKI is described.', 'Monitor INR more frequently in renal impairment.', 'FDA label, Use in Specific Populations (Renal impairment)'),
    ('med_warfarin', 'liver_disease', 'caution', 'Reduced synthesis of clotting factors potentiates warfarin response.', 'Monitor INR and bleeding closely in hepatic impairment.', 'FDA label, Use in Specific Populations (Hepatic impairment)'),
    ('med_amoxicillin', 'hypertension', 'safe', 'No condition-specific precaution in labeling.', 'Standard dosing.', 'FDA label'),
    ('med_amoxicillin', 'diabetes', 'safe', 'No condition-specific precaution in labeling.', 'Standard dosing.', 'FDA label'),
    ('med_amoxicillin', 'pregnant', 'safe', 'Widely used in pregnancy with reassuring safety data; minimal excretion into breast milk.', 'Standard dosing; compatible with breastfeeding.', 'StatPearls: Amoxicillin (Pregnancy/Lactation); FDA label, Use in Specific Populations'),
    ('med_amoxicillin', 'asthma', 'safe', 'No condition-specific precaution in labeling.', 'Standard dosing.', 'FDA label'),
    ('med_amoxicillin', 'peptic_ulcer', 'safe', 'Component of standard H. pylori eradication regimens for peptic ulcer disease.', 'Used with clarithromycin and a PPI per label regimens.', 'FDA label, Indications (H. pylori)'),
    ('med_amoxicillin', 'renal_impairment', 'caution', 'Renally excreted; accumulates when GFR is reduced.', 'Dose adjustment for GFR < 30 mL/min; avoid 875 mg tablets in GFR < 30 per label.', 'FDA label, Dosage in Renal Impairment'),
    ('med_amoxicillin', 'liver_disease', 'safe', 'No hepatic dose adjustment recommended in labeling.', 'Rare hepatotoxicity reported; monitor if clinically indicated.', 'StatPearls: Amoxicillin (Hepatic impairment)'),
    ('med_amoxicillin', 'autoimmune', 'safe', 'No condition-specific precaution in labeling.', 'Standard dosing.', 'FDA label'),
    ('med_coamoxiclav', 'hypertension', 'safe', 'No condition-specific precaution in labeling.', 'Standard dosing.', 'FDA label'),
    ('med_coamoxiclav', 'diabetes', 'safe', 'No condition-specific precaution in labeling.', 'Standard dosing.', 'FDA label'),
    ('med_coamoxiclav', 'pregnant', 'safe', 'Beta-lactams are generally considered compatible with pregnancy (former FDA category B).', 'Use when indicated.', 'StatPearls: Amoxicillin Clavulanate (Pregnancy)'),
    ('med_coamoxiclav', 'asthma', 'safe', 'No condition-specific precaution in labeling.', 'Standard dosing.', 'FDA label'),
    ('med_coamoxiclav', 'renal_impairment', 'caution', 'Both components are renally cleared.', 'Dose adjustment for CrCl < 30 mL/min; avoid 875 mg tablets per label.', 'FDA label, Dosage and Administration (Renal impairment)'),
    ('med_coamoxiclav', 'liver_disease', 'caution', 'Clavulanate-associated cholestatic hepatitis; rare fatalities reported.', 'Use with caution and monitor liver function in hepatic impairment; contraindicated after prior co-amoxiclav-associated hepatic dysfunction.', 'FDA label, Contraindications and Warnings (Hepatic dysfunction); StatPearls'),
    ('med_coamoxiclav', 'autoimmune', 'safe', 'No condition-specific precaution in labeling.', 'Standard dosing.', 'FDA label'),
    ('med_azithromycin', 'hypertension', 'safe', 'No hypertension-specific precaution in labeling.', 'Assess QT risk (e.g., hypokalemia from diuretics, structural heart disease) before use.', 'FDA label, Warnings (QT prolongation)'),
    ('med_azithromycin', 'diabetes', 'safe', 'No condition-specific precaution in labeling.', 'Standard dosing.', 'FDA label'),
    ('med_azithromycin', 'pregnant', 'safe', 'Animal studies showed no fetal harm; commonly used in pregnancy when a macrolide is indicated.', 'Use when clearly indicated.', 'FDA label, Use in Specific Populations (Pregnancy)'),
    ('med_azithromycin', 'asthma', 'safe', 'No asthma-specific precaution in labeling.', 'Standard dosing.', 'FDA label'),
    ('med_azithromycin', 'peptic_ulcer', 'safe', 'No peptic ulcer-specific precaution in labeling.', 'Standard dosing.', 'FDA label'),
    ('med_azithromycin', 'renal_impairment', 'caution', 'Exposure increases in severe renal impairment (GFR < 10 mL/min).', 'Use with caution when GFR < 10 mL/min; no adjustment for milder impairment.', 'FDA label, Use in Specific Populations (Renal impairment)'),
    ('med_azithromycin', 'liver_disease', 'caution', 'Primarily hepatically eliminated; hepatotoxicity including fatal hepatic failure reported.', 'Use with caution; discontinue if signs of hepatitis occur. Pharmacokinetics in hepatic impairment not established.', 'FDA label, Warnings (Hepatotoxicity) and Use in Specific Populations'),
    ('med_azithromycin', 'autoimmune', 'caution', 'Exacerbation of myasthenia gravis and new-onset myasthenic syndrome reported.', 'Use with caution in myasthenia gravis; no specific precaution for other autoimmune conditions.', 'FDA label, Warnings (Exacerbation of myasthenia gravis)'),
    ('med_clarithromycin', 'hypertension', 'caution', 'Hypotension and acute kidney injury reported with CYP3A4-metabolized calcium channel blockers.', 'Monitor blood pressure and renal function when combined with verapamil, amlodipine, diltiazem or nifedipine.', 'FDA label, Warnings (Serious adverse reactions due to concomitant use with other drugs)'),
    ('med_clarithromycin', 'diabetes', 'caution', 'Significant hypoglycemia reported with oral hypoglycemic agents and/or insulin.', 'Monitor blood glucose closely during co-administration.', 'FDA label, Drug Interactions (Oral hypoglycemic agents/insulin)'),
    ('med_clarithromycin', 'pregnant', 'avoid', 'Adverse embryo-fetal outcomes in animal studies.', 'Not recommended in pregnancy except where no alternative therapy is appropriate.', 'FDA label, Warnings (Embryo-fetal toxicity)'),
    ('med_clarithromycin', 'asthma', 'caution', 'Raises serum theophylline concentrations.', 'Monitor theophylline levels if used with clarithromycin.', 'FDA label, Drug Interactions (Theophylline)'),
    ('med_clarithromycin', 'peptic_ulcer', 'safe', 'Component of H. pylori triple therapy for peptic ulcer disease.', 'Used with amoxicillin and a PPI per label regimens; local clarithromycin resistance affects efficacy.', 'FDA label, Indications (H. pylori); StatPearls: Macrolides'),
    ('med_clarithromycin', 'renal_impairment', 'caution', 'Reduced clearance in severe renal impairment; colchicine co-use is contraindicated.', 'Reduce dose by 50% when CrCl < 30 mL/min per label.', 'FDA label, Dosage and Administration (Renal impairment)'),
    ('med_clarithromycin', 'liver_disease', 'caution', 'Hepatic dysfunction including hepatocellular and cholestatic hepatitis reported.', 'Discontinue if hepatitis develops; colchicine co-use is contraindicated in hepatic impairment.', 'FDA label, Warnings (Hepatotoxicity) and Contraindications'),
    ('med_clarithromycin', 'autoimmune', 'caution', 'Exacerbation of myasthenia gravis reported.', 'Use with caution in myasthenia gravis.', 'FDA label, Warnings (Exacerbation of myasthenia gravis)'),
    ('med_ceftriaxone', 'hypertension', 'safe', 'No condition-specific precaution in labeling.', 'Standard dosing.', 'FDA label'),
    ('med_ceftriaxone', 'diabetes', 'safe', 'No condition-specific precaution in labeling.', 'Standard dosing.', 'FDA label'),
    ('med_ceftriaxone', 'pregnant', 'safe', 'No teratogenic effects in animal studies; cephalosporins are generally considered compatible with pregnancy and breastfeeding.', 'Use when clearly needed per label.', 'FDA label, Pregnancy; StatPearls: Third-Generation Cephalosporins'),
    ('med_ceftriaxone', 'asthma', 'safe', 'No condition-specific precaution in labeling.', 'Standard dosing.', 'FDA label'),
    ('med_ceftriaxone', 'peptic_ulcer', 'safe', 'No condition-specific precaution in labeling.', 'Standard dosing.', 'FDA label'),
    ('med_ceftriaxone', 'renal_impairment', 'safe', 'Dual renal and biliary elimination; no adjustment for renal impairment alone.', 'If combined significant hepatic and renal impairment, do not exceed 2 g/day.', 'FDA label, Dosage and Administration'),
    ('med_ceftriaxone', 'liver_disease', 'safe', 'No adjustment for hepatic impairment alone.', 'If combined significant hepatic and renal impairment, do not exceed 2 g/day; biliary pseudolithiasis may occur.', 'FDA label, Dosage and Administration'),
    ('med_ceftriaxone', 'autoimmune', 'safe', 'No condition-specific precaution in labeling.', 'Standard dosing.', 'FDA label'),
    ('med_ciprofloxacin', 'diabetes', 'caution', 'Dysglycemia, including severe hypoglycemia with coma, reported mainly in diabetics on oral hypoglycemics or insulin.', 'Monitor blood glucose; discontinue if hypoglycemia occurs.', 'FDA label, Warnings (Blood glucose disturbances)'),
    ('med_ciprofloxacin', 'pregnant', 'caution', 'Human data do not show increased malformations, but safety is not established.', 'Reserve for compelling indications without suitable alternatives; breastfeeding not recommended during therapy per label.', 'FDA label, Pregnancy/Lactation; StatPearls: Ciprofloxacin'),
    ('med_ciprofloxacin', 'asthma', 'caution', 'CYP1A2 inhibition markedly raises theophylline levels (serious and fatal reactions reported).', 'Avoid with theophylline; if unavoidable, monitor theophylline levels.', 'FDA label, Warnings and Drug Interactions (Theophylline)'),
    ('med_ciprofloxacin', 'renal_impairment', 'caution', 'Renally cleared; accumulates with reduced CrCl.', 'Dose adjustment when CrCl <= 50 mL/min per label.', 'FDA label, Dosage in Renal Impairment'),
    ('med_ciprofloxacin', 'liver_disease', 'caution', 'Hepatotoxicity reported; transient transaminase rises or cholestatic jaundice more likely with prior liver damage.', 'Discontinue if signs of hepatitis occur.', 'FDA label, Warnings (Hepatotoxicity); StatPearls: Ciprofloxacin'),
    ('med_ciprofloxacin', 'autoimmune', 'caution', 'Boxed warning for myasthenia gravis exacerbation; tendon rupture risk higher with concomitant corticosteroids.', 'Avoid in known myasthenia gravis; use caution in patients on systemic corticosteroids.', 'FDA label, Boxed Warning and Warnings (Tendinitis and tendon rupture)'),
    ('med_nitrofurantoin', 'diabetes', 'caution', 'Diabetes is a listed risk factor for nitrofurantoin peripheral neuropathy.', 'Monitor for paresthesias; discontinue at first signs of neuropathy.', 'FDA label, Warnings (Neuropathy)'),
    ('med_nitrofurantoin', 'pregnant', 'caution', 'Risk of hemolytic anemia in the neonate when given near delivery.', 'Contraindicated at term (38-42 weeks), during labor and delivery, or when labor is imminent.', 'FDA label, Contraindications'),
    ('med_nitrofurantoin', 'renal_impairment', 'avoid', 'Reduced urinary concentration (loss of efficacy) and accumulation causing toxicity (e.g., neuropathy).', 'Contraindicated with anuria, oliguria or CrCl < 60 mL/min per US label.', 'FDA label, Contraindications; StatPearls: Nitrofurantoin'),
    ('med_nitrofurantoin', 'liver_disease', 'caution', 'Hepatic reactions including hepatitis, cholestatic jaundice and hepatic necrosis (rarely fatal) reported.', 'Monitor liver function with prolonged use; contraindicated after prior nitrofurantoin-associated cholestatic jaundice.', 'FDA label, Contraindications and Warnings (Hepatic reactions)'),
    ('med_doxycycline', 'hypertension', 'safe', 'No condition-specific precaution in labeling.', 'Standard dosing.', 'FDA label'),
    ('med_doxycycline', 'diabetes', 'safe', 'No condition-specific precaution in labeling.', 'Standard dosing.', 'FDA label'),
    ('med_doxycycline', 'pregnant', 'avoid', 'Tetracyclines cause tooth discoloration/enamel hypoplasia and may affect fetal bone growth when given during tooth development (second half of pregnancy).', 'Generally avoided in pregnancy; use only if the benefit outweighs the risk.', 'FDA label, Warnings (Tooth development) and Pregnancy; StatPearls: Doxycycline'),
    ('med_doxycycline', 'asthma', 'safe', 'No condition-specific precaution in labeling.', 'Standard dosing.', 'FDA label'),
    ('med_doxycycline', 'renal_impairment', 'safe', 'Half-life (18-22 h) essentially unchanged in renal impairment; unlike other tetracyclines, not dependent on renal excretion.', 'No renal dose adjustment required.', 'StatPearls: Doxycycline (Renal impairment)'),
    ('med_doxycycline', 'liver_disease', 'caution', 'Rare hepatotoxicity reported; listed as a relative contraindication.', 'Monitor liver function if used in hepatic disease.', 'StatPearls: Doxycycline (Hepatic impairment)'),
    ('med_rifampicin', 'diabetes', 'caution', 'Enzyme induction substantially lowers exposure to oral antidiabetic agents (e.g., sulfonylureas).', 'Monitor glycemic control and adjust antidiabetic therapy during and after rifampicin.', 'FDA label, Drug Interactions'),
    ('med_rifampicin', 'pregnant', 'safe', 'Considered usable in pregnancy as part of first-line TB therapy; no congenital malformation signal.', 'Use in the last weeks of pregnancy may cause postnatal hemorrhage in mother and infant; vitamin K may be indicated.', 'StatPearls: Rifampin and Antitubercular Medications; FDA label, Pregnancy'),
    ('med_rifampicin', 'renal_impairment', 'safe', 'Primarily hepatobiliary elimination.', 'No dosage adjustment required in renal impairment.', 'StatPearls: Rifampin (Renal impairment)'),
    ('med_rifampicin', 'liver_disease', 'caution', 'Hepatotoxicity ranging to fulminant liver failure; risk higher with pre-existing liver disease and with isoniazid.', 'Use only when necessary with close LFT monitoring; discontinue if hepatic damage occurs.', 'FDA label, Warnings (Hepatotoxicity); StatPearls: Rifampin'),
    ('med_rifampicin', 'autoimmune', 'caution', 'Enzyme induction substantially decreases corticosteroid exposure.', 'Corticosteroid doses may need adjustment during rifampicin therapy.', 'FDA label, Drug Interactions (Corticosteroids)'),
    ('med_isoniazid', 'diabetes', 'caution', 'Diabetes predisposes to isoniazid peripheral neuropathy.', 'Give pyridoxine supplementation to patients with diabetes.', 'FDA label, Precautions (Peripheral neuropathy); StatPearls: Isoniazid'),
    ('med_isoniazid', 'pregnant', 'safe', 'Benefits outweigh risks for active TB; isoniazid is considered usable in pregnancy.', 'Give with pyridoxine; the boxed warning notes increased hepatitis risk in the postpartum period.', 'StatPearls: Isoniazid and Antitubercular Medications; FDA label, Boxed Warning'),
    ('med_isoniazid', 'renal_impairment', 'safe', 'Half-life may be prolonged in slow acetylators, but full doses are generally used.', 'No routine dose adjustment; pyridoxine supplementation advised.', 'StatPearls: Isoniazid (Renal impairment)'),
    ('med_isoniazid', 'liver_disease', 'caution', 'Boxed warning for severe, sometimes fatal hepatitis; chronic liver disease increases risk.', 'Contraindicated in acute liver disease or prior INH liver injury; otherwise use with frequent LFT monitoring.', 'FDA label, Boxed Warning and Contraindications; StatPearls: Isoniazid'),
    ('med_isoniazid', 'autoimmune', 'caution', 'Isoniazid can induce a drug-induced lupus syndrome (about 1% of patients).', 'Consider drug-induced lupus if new arthralgia, serositis or positive ANA develop.', 'StatPearls: Isoniazid (Adverse effects)'),
    ('med_pyrazinamide', 'diabetes', 'caution', 'Label advises caution in patients with diabetes mellitus, in whom glycemic management may be more difficult.', 'Monitor glycemic control during therapy.', 'FDA label, Precautions'),
    ('med_pyrazinamide', 'pregnant', 'caution', 'Animal reproduction studies not conducted; US practice has avoided it in pregnancy, whereas WHO regimens include it.', 'Use in pregnancy per specialist/national TB program guidance.', 'FDA label, Pregnancy; StatPearls: Antitubercular Medications'),
    ('med_pyrazinamide', 'liver_disease', 'avoid', 'Dose-related hepatotoxicity; the most hepatotoxic of the first-line agents.', 'Contraindicated in severe hepatic damage; obtain baseline and periodic LFTs.', 'FDA label, Contraindications and Warnings'),
    ('med_ethambutol', 'pregnant', 'safe', 'Does not appear to be teratogenic; considered safe in pregnancy as part of TB therapy.', 'Standard weight-based dosing.', 'StatPearls: Ethambutol and Antitubercular Medications'),
    ('med_ethambutol', 'renal_impairment', 'caution', 'Renally excreted; accumulation increases optic toxicity risk.', 'Reduce dosing frequency (three times weekly) when CrCl < 30 mL/min.', 'StatPearls: Ethambutol; FDA label, Precautions'),
    ('med_ethambutol', 'liver_disease', 'caution', 'Hepatic toxicities, including fatalities, reported (usually with other hepatotoxic TB drugs).', 'Baseline and periodic liver function monitoring.', 'FDA label, Warnings; StatPearls: Ethambutol'),
    ('med_artemether_lumefantrine', 'pregnant', 'safe', 'WHO (Nov 2022) strongly recommends artemether-lumefantrine for uncomplicated falciparum malaria in all trimesters, including the first.', 'First-trimester exposure data (~500 women in label) show no increase in adverse outcomes; malaria itself is high-risk in pregnancy.', 'WHO guideline update via MMV; FDA label, Pregnancy'),
    ('med_artemether_lumefantrine', 'renal_impairment', 'caution', 'Not studied in severe renal impairment.', 'Use with caution in severe renal impairment; no dose adjustment specified for mild-moderate impairment.', 'FDA label, Use in Specific Populations'),
    ('med_artemether_lumefantrine', 'liver_disease', 'caution', 'Not studied in severe hepatic impairment.', 'Use with caution in severe hepatic impairment; no dose adjustment specified for mild-moderate impairment.', 'FDA label, Use in Specific Populations'),
    ('med_oseltamivir', 'hypertension', 'safe', 'No condition-specific precaution in labeling.', 'Standard dosing.', 'FDA label'),
    ('med_oseltamivir', 'diabetes', 'safe', 'No condition-specific precaution in labeling; patients with chronic conditions are a priority group for antiviral treatment.', 'Standard dosing.', 'FDA label; StatPearls: Oseltamivir'),
    ('med_oseltamivir', 'pregnant', 'safe', 'Epidemiological data show no increased risk of birth defects in any trimester; CDC recommends it as the preferred agent in pregnancy and postpartum.', 'Standard dosing; present in breast milk at low levels unlikely to harm the infant.', 'FDA label, Pregnancy/Lactation; StatPearls: Oseltamivir'),
    ('med_oseltamivir', 'asthma', 'safe', 'Oral agent with no bronchospasm warning in labeling (unlike inhaled neuraminidase inhibitors).', 'Standard dosing.', 'FDA label; Goodman & Gilman''s 14th ed.'),
    ('med_oseltamivir', 'peptic_ulcer', 'safe', 'No condition-specific precaution in labeling.', 'Taking with food may reduce nausea.', 'FDA label'),
    ('med_oseltamivir', 'renal_impairment', 'caution', 'Active metabolite is renally eliminated and accumulates.', 'Dose adjustment when CrCl <= 60 mL/min, and in hemodialysis/CAPD, per label.', 'FDA label, Dosage in Renal Impairment'),
    ('med_oseltamivir', 'liver_disease', 'safe', 'No dosage adjustment for mild-to-moderate hepatic impairment.', 'Not studied in severe hepatic impairment (Child-Pugh C).', 'FDA label, Use in Specific Populations; StatPearls: Oseltamivir'),
    ('med_oseltamivir', 'autoimmune', 'safe', 'No condition-specific precaution in labeling.', 'Standard dosing.', 'FDA label'),
    ('med_nirmatrelvir_ritonavir', 'hypertension', 'caution', 'Hypertension is a labeled adverse reaction and ritonavir raises levels of calcium channel blockers and other antihypertensives.', 'Review antihypertensive co-medication (e.g., amlodipine) for dose reduction and monitor blood pressure.', 'FDA label (Paxlovid), Adverse Reactions / Drug Interactions'),
    ('med_nirmatrelvir_ritonavir', 'diabetes', 'safe', 'No diabetes-specific restriction in labeling; diabetes is a high-risk condition for which treatment is indicated.', 'Screen co-medications for CYP3A interactions as for any patient.', 'FDA label (Paxlovid), Indications; StatPearls'),
    ('med_nirmatrelvir_ritonavir', 'pregnant', 'caution', 'Human data on nirmatrelvir are limited; ritonavir data show no increase in birth defects, and COVID-19 carries maternal and fetal risk.', 'Not contraindicated; weigh benefit against risk (StatPearls supports use in pregnancy when indicated).', 'FDA label (Paxlovid), Use in Specific Populations; StatPearls'),
    ('med_nirmatrelvir_ritonavir', 'asthma', 'caution', 'Ritonavir increases systemic exposure to CYP3A-metabolized inhaled corticosteroids (e.g., budesonide, fluticasone) and salmeterol.', 'Review inhaler regimen for CYP3A interactions; monitor for corticosteroid or LABA adverse effects.', 'FDA label (Paxlovid), Drug Interactions; Symbicort label'),
